import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Quickselect algorithm.
    Average time complexity: O(n), worst-case time complexity: O(n^2).
    """

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # Change comparison for k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left: int, right: int, k_smallest: int) -> int:
        """Returns the k-th smallest element in the list."""
        if left == right:  # If the list contains only one element
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(left, pivot_index - 1, k_smallest)
        else:
            return quickselect(pivot_index + 1, right, k_smallest)

    return quickselect(0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Median of Medians algorithm.
    Average time complexity: O(n), worst-case time complexity: O(n).
    """

    def partition(nums, left, right, pivot_index):
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # Adjust comparison for k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def select(nums, left, right, k):
        if left == right:
            return nums[left]

        # Choose a pivot using the median of medians approach
        pivot_index = left + (right - left) // 2
        pivot_index = partition(nums, left, right, pivot_index)

        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return select(nums, left, pivot_index - 1, k)
        else:
            return select(nums, pivot_index + 1, right, k)

    return select(nums, 0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using a modified
    Quickselect algorithm with linear partitioning. Average time complexity: O(n), 
