        nums[store_index], nums[high] = nums[high], nums[store_index]
        return store_index

    def quickselect(low: int, high: int, k_smallest: int) -> int:
        if low == high:
            return nums[low]

        pivot_index = low + (high - low) // 2
        pivot_index = partition(low, high, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(low, pivot_index - 1, k_smallest)
